20	namespace vortex {
21	
22	class Core;
23	
24	// Type-erased base used by Core to keep heterogeneous FuncUnit<N_BLOCKS>
25	// instances in a single container and to bind/probe their I/O channels.
26	class FuncUnitBase {
27	public:
28		virtual ~FuncUnitBase() = default;
29		virtual SimChannel<instr_trace_t*>& input(uint32_t b) = 0;
30		virtual SimChannel<instr_trace_t*>& output(uint32_t b) = 0;
31		virtual uint32_t num_blocks() const = 0;
32	};
33	
34	// FuncUnit pipelines have NUM_BLOCKS physical lanes, not VX_CFG_ISSUE_WIDTH. The
35	// dispatcher upstream aggregates VX_CFG_ISSUE_WIDTH issue ports onto NUM_BLOCKS
36	// execution ports; commit downstream fans them back out to per-iw arbiters
37	// using trace->wid.
38	template <uint32_t NUM_BLOCKS>
39	class FuncUnit : public FuncUnitBase, public SimObject<FuncUnit<NUM_BLOCKS>> {
40	public:
41		static constexpr uint32_t kNumBlocks = NUM_BLOCKS;
42	
43		std::array<SimChannel<instr_trace_t*>, NUM_BLOCKS> Inputs;
44		std::array<SimChannel<instr_trace_t*>, NUM_BLOCKS> Outputs;
45	
46		FuncUnit(const SimContext& ctx, const char* name, Core* core)
47			: SimObject<FuncUnit<NUM_BLOCKS>>(ctx, name)
48			, Inputs(make_sim_channels<instr_trace_t*, NUM_BLOCKS>(this))
49			, Outputs(make_sim_channels<instr_trace_t*, NUM_BLOCKS>(this))
50			, core_(core)
51		{}
52	
53		virtual ~FuncUnit() {}
54	
55		// FuncUnitBase polymorphic accessors for the type-erased Core wiring.
56		SimChannel<instr_trace_t*>& input(uint32_t b) override { return Inputs[b]; }
57		SimChannel<instr_trace_t*>& output(uint32_t b) override { return Outputs[b]; }
58		uint32_t num_blocks() const override { return NUM_BLOCKS; }
59	
60	protected:
61		// SimObject<FuncUnit<N>>::on_tick is a non-virtual no-op — these
62		// declarations introduce a new virtual that the CRTP do_tick()
63		// resolves through, so derived FUs can override.
64		virtual void on_reset() {}
65		virtual void on_tick() = 0;
66	
67		friend class SimObject<FuncUnit<NUM_BLOCKS>>;
68	
69		Core* core_;
70	};
71	
72	}
