25	using namespace vortex;
26	
27	AluUnit::AluUnit(const SimContext& ctx, const char* name, Core* core)
28		: FuncUnit<VX_CFG_NUM_ALU_BLOCKS>(ctx, name, core)
29	{}
30	
31	uint32_t AluUnit::latency_of(const instr_trace_t* trace) const {
32		if (std::get_if<AluType>(&trace->op_type)) {
33			auto alu_type = std::get<AluType>(trace->op_type);
34			switch (alu_type) {
35			case AluType::LUI:
36			case AluType::AUIPC:
37			case AluType::ADD:
38			case AluType::SUB:
39			case AluType::SLL:
40			case AluType::SRL:
41			case AluType::SRA:
42			case AluType::SLT:
43			case AluType::SLTU:
44			case AluType::XOR:
45			case AluType::AND:
46			case AluType::OR:
47			case AluType::CZERO:
48				return 2;
49			default:
50				std::abort();
51			}
52		} else if (std::get_if<VoteType>(&trace->op_type)) {
53			return 2;
54		} else if (std::get_if<ShflType>(&trace->op_type)) {
55			return 2;
56		} else if (std::get_if<WgatherType>(&trace->op_type)) {
57			return 2;
58		} else if (std::get_if<BrType>(&trace->op_type)) {
59			auto br_type = std::get<BrType>(trace->op_type);
60			switch (br_type) {
61			case BrType::BR:
62			case BrType::JAL:
63			case BrType::JALR:
64			case BrType::SYS:
65				return 2;
66			default:
67				std::abort();
68			}
69		} else if (std::get_if<MdvType>(&trace->op_type)) {
70			auto mdv_type = std::get<MdvType>(trace->op_type);
71			switch (mdv_type) {
72			case MdvType::MUL:
73			case MdvType::MULHU:
74			case MdvType::MULH:
75			case MdvType::MULHSU:
76				return 2;
77			case MdvType::DIV:
78			case MdvType::DIVU:
79			case MdvType::REM:
80			case MdvType::REMU:
81				return VX_CFG_XLEN+2;
82			default:
83				std::abort();
84			}
85		}
86		std::abort();
87	}
88	
89	void AluUnit::execute(instr_trace_t* trace) {
90		auto& sched = core_->scheduler();
91		auto& warp = sched.warp(trace->wid);
92		// Use trace->tmask captured at issue for per-thread active checks.
93		// `warp.tmask` is the live warp state and may change due to divergent
94		// control flow before this trace executes; the rest of the pipeline
95		// (commit, writeback) keys off trace->tmask, so a mismatch leaves lanes
96		// with stale dst_data. See LsuUnit::execute for the same pattern.
97		auto& tmask = trace->tmask;
98		auto& instr = *trace->instr_ptr;
99		auto instrArgs = instr.get_args();
100		uint32_t num_threads = VX_CFG_NUM_THREADS;
101		auto& rs1_data = trace->src_data[0];
102		auto& rs2_data = trace->src_data[1];
103		auto& rs3_data = trace->src_data[2];
104	
105		// derive thread bounds from operand mask
106		uint32_t thread_start = 0;
107		for (; thread_start < num_threads; ++thread_start) {
108			if (tmask.test(thread_start))
109				break;
110		}
111		int32_t thread_last = num_threads - 1;
112		for (; thread_last >= 0; --thread_last) {
113			if (tmask.test(thread_last))
114				break;
115		}
116	
117		bool is_w_enabled = false;
118	#ifdef VX_CFG_XLEN_64
119		is_w_enabled = true;
120	#endif
121	
122		// always size dst_data so per-op compute can write unconditionally;
123		// commit_writeback gates regfile actual write on wb (skipped for x0 dst).
124		trace->dst_data.assign(num_threads, reg_data_t{});
125		auto& rd_data = trace->dst_data;
126	
127		if (std::get_if<AluType>(&trace->op_type)) {
128			auto alu_type = std::get<AluType>(trace->op_type);
129			auto aluArgs = std::get<IntrAluArgs>(instrArgs);
130			Word imm = sext<Word>(aluArgs.imm, 32);
131			switch (alu_type) {
132			case AluType::LUI: {
133				for (uint32_t t = thread_start; t < num_threads; ++t) {
134					if (!tmask.test(t)) continue;
135					rd_data[t].i = imm;
136				}
137			} break;
138			case AluType::AUIPC: {
139				for (uint32_t t = thread_start; t < num_threads; ++t) {
140					if (!tmask.test(t)) continue;
141					rd_data[t].i = imm + trace->PC;
142				}
143			} break;
144			case AluType::ADD: {
145				for (uint32_t t = thread_start; t < num_threads; ++t) {
146					if (!tmask.test(t)) continue;
147					if (is_w_enabled && aluArgs.is_w) {
148						auto result = rs1_data[t].i32 + (int32_t)(aluArgs.is_imm ? aluArgs.imm : rs2_data[t].i32);
149						rd_data[t].i = sext((uint64_t)result, 32);
150					} else {
151						rd_data[t].i = rs1_data[t].i + (aluArgs.is_imm ? imm : rs2_data[t].i);
152					}
153				}
154			} break;
155			case AluType::SUB: {
156				for (uint32_t t = thread_start; t < num_threads; ++t) {
157					if (!tmask.test(t)) continue;
158					if (is_w_enabled && aluArgs.is_w) {
159						auto result = rs1_data[t].i32 - (int32_t)(aluArgs.is_imm ? aluArgs.imm : rs2_data[t].i32);
160						rd_data[t].i = sext((uint64_t)result, 32);
161					} else {
162						rd_data[t].i = rs1_data[t].i - (aluArgs.is_imm ? imm : rs2_data[t].i);
163					}
164				}
165			} break;
166			case AluType::SLT: {
167				for (uint32_t t = thread_start; t < num_threads; ++t) {
168					if (!tmask.test(t)) continue;
169					rd_data[t].i = rs1_data[t].i < (aluArgs.is_imm ? WordI(imm) : rs2_data[t].i);
170				}
171			} break;
172			case AluType::SLTU: {
173				for (uint32_t t = thread_start; t < num_threads; ++t) {
174					if (!tmask.test(t)) continue;
175					rd_data[t].i = rs1_data[t].u < (aluArgs.is_imm ? imm : rs2_data[t].u);
176				}
177			} break;
178			case AluType::SLL: {
179				Word shamt_mask = (Word(1) << log2up(VX_CFG_XLEN)) - 1;
180				for (uint32_t t = thread_start; t < num_threads; ++t) {
181					if (!tmask.test(t)) continue;
182					if (is_w_enabled && aluArgs.is_w) {
183						uint32_t shamt = (aluArgs.is_imm ? aluArgs.imm : rs2_data[t].i32) & shamt_mask;
184						uint32_t result = (uint32_t)rs1_data[t].i << shamt;
185						rd_data[t].i = sext((uint64_t)result, 32);
186					} else {
187						Word shamt = (aluArgs.is_imm ? imm : rs2_data[t].i) & shamt_mask;
188						rd_data[t].i = rs1_data[t].i << shamt;
189					}
190				}
191			} break;
192			case AluType::SRA: {
193				Word shamt_mask = (Word(1) << log2up(VX_CFG_XLEN)) - 1;
194				for (uint32_t t = thread_start; t < num_threads; ++t) {
195					if (!tmask.test(t)) continue;
196					if (is_w_enabled && aluArgs.is_w) {
197						uint32_t shamt = (aluArgs.is_imm ? aluArgs.imm : rs2_data[t].i32) & shamt_mask;
198						uint32_t result = (int32_t)rs1_data[t].i >> shamt;
199						rd_data[t].i = sext((uint64_t)result, 32);
200					} else {
201						Word shamt = (aluArgs.is_imm ? imm : rs2_data[t].i) & shamt_mask;
202						rd_data[t].i = rs1_data[t].i >> shamt;
203					}
204				}
205			} break;
206			case AluType::SRL: {
207				Word shamt_mask = (Word(1) << log2up(VX_CFG_XLEN)) - 1;
208				for (uint32_t t = thread_start; t < num_threads; ++t) {
209					if (!tmask.test(t)) continue;
210					if (is_w_enabled && aluArgs.is_w) {
211						uint32_t shamt = (aluArgs.is_imm ? aluArgs.imm : rs2_data[t].i32) & shamt_mask;
212						uint32_t result = (uint32_t)rs1_data[t].i >> shamt;
213						rd_data[t].i = sext((uint64_t)result, 32);
214					} else {
215						Word shamt = (aluArgs.is_imm ? imm : rs2_data[t].i) & shamt_mask;
216						rd_data[t].i = rs1_data[t].u >> shamt;
217					}
218				}
219			} break;
220			case AluType::AND: {
221				for (uint32_t t = thread_start; t < num_threads; ++t) {
222					if (!tmask.test(t)) continue;
223					rd_data[t].i = rs1_data[t].i & (aluArgs.is_imm ? imm : rs2_data[t].i);
224				}
225			} break;
226			case AluType::OR: {
227				for (uint32_t t = thread_start; t < num_threads; ++t) {
228					if (!tmask.test(t)) continue;
229					rd_data[t].i = rs1_data[t].i | (aluArgs.is_imm ? imm : rs2_data[t].i);
230				}
231			} break;
232			case AluType::XOR: {
233				for (uint32_t t = thread_start; t < num_threads; ++t) {
234					if (!tmask.test(t)) continue;
235					rd_data[t].i = rs1_data[t].i ^ (aluArgs.is_imm ? imm : rs2_data[t].i);
236				}
237			} break;
238			case AluType::CZERO: {
239				for (uint32_t t = thread_start; t < num_threads; ++t) {
240					if (!tmask.test(t)) continue;
241					bool cond = (rs2_data[t].i == 0) ^ aluArgs.imm;
242					rd_data[t].i = cond ? 0 : rs1_data[t].i;
243				}
244			} break;
245			default:
246				std::abort();
247			}
248			DT(3, this->name() << " execute: op=" << alu_type << ", " << *trace);
249		} else if (std::get_if<VoteType>(&trace->op_type)) {
250			auto vote_type = std::get<VoteType>(trace->op_type);
251			bool has_vote_true = false;
252			bool has_vote_false = false;
253			Word ballot = 0;
254			for (uint32_t t = thread_start; t < num_threads; ++t) {
255				if (!tmask.test(t)) continue;
256				auto is_pred = rs1_data[t].i & 0x1;
257				if (is_pred) {
258					has_vote_true = true;
259					ballot |= (Word(1) << t);
260				} else {
261					has_vote_false = true;
262				}
263			}
264			for (uint32_t t = thread_start; t < num_threads; ++t) {
265				switch (vote_type) {
266				case VoteType::ALL: rd_data[t].i = !has_vote_false; break;
267				case VoteType::ANY: rd_data[t].i = has_vote_true; break;
268				case VoteType::UNI: rd_data[t].i = !has_vote_true || !has_vote_false; break;
269				case VoteType::BAL: rd_data[t].i = ballot; break;
270				default: std::abort();
271				}
272			}
273		} else if (std::get_if<ShflType>(&trace->op_type)) {
274			auto shfl_type = std::get<ShflType>(trace->op_type);
275			for (uint32_t t = thread_start; t < num_threads; ++t) {
276				if (!tmask.test(t)) continue;
277				auto bc  = rs2_data[t].i;
278				int bval = (bc >>  0) & 0x3f;
279				int cval = (bc >>  6) & 0x3f;
280				int mask = (bc >> 12) & 0x3f;
281				int maxLane = (t & mask) | (cval & ~mask);
282				int minLane = (t & mask);
283				int lane = 0;
284				int pval = 0;
285				switch (shfl_type) {
286				case ShflType::UP:   lane = t - bval; pval = (lane >= minLane); break;
287				case ShflType::DOWN: lane = t + bval; pval = (lane <= maxLane); break;
288				case ShflType::BFLY: lane = t ^ bval; pval = (lane <= maxLane); break;
289				case ShflType::IDX:  lane = minLane | (bval & ~mask); pval = (lane <= maxLane); break;
290				default: std::abort();
291				}
292				if (!pval) lane = t;
293				if (lane < (int)num_threads) {
294					rd_data[t].i = rs1_data[lane].i;
295				} else {
296					rd_data[t].i = rs1_data[t].i;
297				}
298			}
299		} else if (std::get_if<WgatherType>(&trace->op_type)) {
300			// Each group of 4 lanes operates independently; the nominal source lane
301			// (group_base + src_offset) is suppressed by clearing its tmask bit so
302			// the standard writeback path skips it (regfile keeps its prior value).
303			// When that nominal lane is masked (partial warp), the read falls back
304			// to the last active lane — mirrors VX_alu_int.sv's last_tid select.
305			auto wgArgs = std::get<IntrWgatherArgs>(instrArgs);
306			uint32_t src_offset = wgArgs.src_lane;
307			// Snapshot the issue-time active mask: the loop below mutates trace->tmask
308			// (which `tmask` aliases) to suppress source lanes, so source-lane liveness
309			// must be judged against the pre-suppression mask, not the live one.
310			auto active = tmask;
311			uint32_t last_tid = thread_start;
312			for (uint32_t t = thread_start; t < num_threads; ++t)
313				if (active.test(t)) last_tid = t;
314			// WGATHER writes the FULL nibble (every non-source lane) regardless of
315			// the active mask, so the gathered value is materialised even in masked
316			// lanes; source lanes stay suppressed (keep their self value). Reads fall
317			// back to the last active lane when the nominal source is masked.
318			for (uint32_t t = thread_start; t < num_threads; ++t) {
319				if ((t & 0x3u) == src_offset) {
320					trace->tmask.reset(t); // suppress writeback for source lane
321					continue;
322				}
323				trace->tmask.set(t);       // force-write non-source lane
324				uint32_t nominal = (t & ~0x3u) + src_offset;
325				uint32_t sl      = active.test(nominal) ? nominal : last_tid;
326				uint32_t offset  = (t - nominal) & 0x3u;
327				if      (offset == 1) rd_data[t].i = rs1_data[sl].i;
328				else if (offset == 2) rd_data[t].i = rs2_data[sl].i;
329				else if (offset == 3) rd_data[t].i = rs3_data[sl].i;
330			}
331		} else if (std::get_if<BrType>(&trace->op_type)) {
332			auto br_type = std::get<BrType>(trace->op_type);
333			auto brArgs = std::get<IntrBrArgs>(instrArgs);
334			Word offset = sext<Word>(brArgs.offset, 32);
335			switch (br_type) {
336			case BrType::BR: {
337				bool curr_taken = false;
338				uint32_t t = static_cast<uint32_t>(thread_last);
339				switch (brArgs.cmp) {
340				case 0: curr_taken = (rs1_data[t].i == rs2_data[t].i); break;
341				case 1: curr_taken = (rs1_data[t].i != rs2_data[t].i); break;
342				case 4: curr_taken = (rs1_data[t].i <  rs2_data[t].i); break;
343				case 5: curr_taken = (rs1_data[t].i >= rs2_data[t].i); break;
344				case 6: curr_taken = (rs1_data[t].u <  rs2_data[t].u); break;
345				case 7: curr_taken = (rs1_data[t].u >= rs2_data[t].u); break;
346				default: std::abort();
347				}
348				if (curr_taken) {
349					warp.PC = trace->PC + offset;
350				}
351				core_->perf_stats().branches += 1;
352			} break;
353			case BrType::JAL: {
354				// RVC source returns PC+2; full RV32I returns PC+4.
355				Word link_pc = trace->PC + (brArgs.is_rvc ? 2 : 4);
356				for (uint32_t t = thread_start; t < num_threads; ++t) {
357					if (!tmask.test(t)) continue;
358					rd_data[t].i = link_pc;
359				}
360				warp.PC = trace->PC + offset;
361				core_->perf_stats().branches += 1;
362			} break;
363			case BrType::JALR: {
364				// RVC source returns PC+2; full RV32I returns PC+4.
365				Word link_pc = trace->PC + (brArgs.is_rvc ? 2 : 4);
366				for (uint32_t t = thread_start; t < num_threads; ++t) {
367					if (!tmask.test(t)) continue;
368					rd_data[t].i = link_pc;
369				}
370				warp.PC = rs1_data[thread_last].i + offset;
371				core_->perf_stats().branches += 1;
372			} break;
373			case BrType::SYS:
374				switch (brArgs.offset) {
375				// ECALL / EBREAK: synchronous trap — redirect warp PC to mtvec.
376				case 0x000: sched.trigger_ecall(trace->wid, trace->PC);  break;
377				case 0x001: sched.trigger_ebreak(trace->wid, trace->PC); break;
378				// URET / SRET / MRET: trap return — restore warp PC from mepc.
379				case 0x002: case 0x102: case 0x302: sched.mret(trace->wid); break;
380				default: std::abort();
381				}
382				core_->perf_stats().branches += 1;
383				break;
384			default:
385				std::abort();
386			}
387			DT(3, this->name() << " execute: op=" << br_type << ", " << *trace);
388		} else if (std::get_if<MdvType>(&trace->op_type)) {
389			auto mdv_type = std::get<MdvType>(trace->op_type);
390			auto mdvArgs = std::get<IntrMdvArgs>(instrArgs);
391			switch (mdv_type) {
392			case MdvType::MUL: {
393				for (uint32_t t = thread_start; t < num_threads; ++t) {
394					if (!tmask.test(t)) continue;
395					if (is_w_enabled && mdvArgs.is_w) {
396						auto product = rs1_data[t].i32 * rs2_data[t].i32;
397						rd_data[t].i = sext((uint64_t)product, 32);
398					} else {
399						rd_data[t].i = rs1_data[t].i * rs2_data[t].i;
400					}
401				}
402			} break;
403			case MdvType::MULH: {
404				for (uint32_t t = thread_start; t < num_threads; ++t) {
405					if (!tmask.test(t)) continue;
406					auto first = static_cast<DWordI>(rs1_data[t].i);
407					auto second = static_cast<DWordI>(rs2_data[t].i);
408					rd_data[t].i = (first * second) >> VX_CFG_XLEN;
409				}
410			} break;
411			case MdvType::MULHSU: {
412				for (uint32_t t = thread_start; t < num_threads; ++t) {
413					if (!tmask.test(t)) continue;
414					auto first = static_cast<DWordI>(rs1_data[t].i);
415					auto second = static_cast<DWord>(rs2_data[t].u);
416					rd_data[t].i = (first * second) >> VX_CFG_XLEN;
417				}
418			} break;
419			case MdvType::MULHU: {
420				for (uint32_t t = thread_start; t < num_threads; ++t) {
421					if (!tmask.test(t)) continue;
422					auto first = static_cast<DWord>(rs1_data[t].u);
423					auto second = static_cast<DWord>(rs2_data[t].u);
424					rd_data[t].i = (first * second) >> VX_CFG_XLEN;
425				}
426			} break;
427			case MdvType::DIV: {
428				for (uint32_t t = thread_start; t < num_threads; ++t) {
429					if (!tmask.test(t)) continue;
430					if (is_w_enabled && mdvArgs.is_w) {
431						auto dividen = rs1_data[t].i32;
432						auto divisor = rs2_data[t].i32;
433						int32_t largest_negative = 0x80000000;
434						int32_t quotient;
435						if (divisor == 0)                                   quotient = -1;
436						else if (dividen == largest_negative && divisor == -1) quotient = dividen;
437						else                                                quotient = dividen / divisor;
438						rd_data[t].i = sext((uint64_t)quotient, 32);
439					} else {
440						auto dividen = rs1_data[t].i;
441						auto divisor = rs2_data[t].i;
442						auto largest_negative = WordI(1) << (VX_CFG_XLEN-1);
443						WordI quotient;
444						if (divisor == 0)                                   quotient = -1;
445						else if (dividen == largest_negative && divisor == -1) quotient = dividen;
446						else                                                quotient = dividen / divisor;
447						rd_data[t].i = quotient;
448					}
449				}
450			} break;
451			case MdvType::DIVU: {
452				for (uint32_t t = thread_start; t < num_threads; ++t) {
453					if (!tmask.test(t)) continue;
454					if (is_w_enabled && mdvArgs.is_w) {
455						auto dividen = rs1_data[t].u32;
456						auto divisor = rs2_data[t].u32;
457						uint32_t quotient;
458						if (divisor != 0) quotient = dividen / divisor;
459						else              quotient = -1;
460						rd_data[t].i = sext((uint64_t)quotient, 32);
461					} else {
462						auto dividen = rs1_data[t].u;
463						auto divisor = rs2_data[t].u;
464						Word quotient;
465						if (divisor != 0) quotient = dividen / divisor;
466						else              quotient = -1;
467						rd_data[t].i = quotient;
468					}
469				}
470			} break;
471			case MdvType::REM: {
472				for (uint32_t t = thread_start; t < num_threads; ++t) {
473					if (!tmask.test(t)) continue;
474					if (is_w_enabled && mdvArgs.is_w) {
475						auto dividen = rs1_data[t].i32;
476						auto divisor = rs2_data[t].i32;
477						int32_t largest_negative = 0x80000000;
478						int32_t remainder;
479						if (divisor == 0)                                   remainder = dividen;
480						else if (dividen == largest_negative && divisor == -1) remainder = 0;
481						else                                                remainder = dividen % divisor;
482						rd_data[t].i = sext((uint64_t)remainder, 32);
483					} else {
484						auto dividen = rs1_data[t].i;
485						auto divisor = rs2_data[t].i;
486						auto largest_negative = WordI(1) << (VX_CFG_XLEN-1);
487						WordI remainder;
488						if (rs2_data[t].i == 0)                             remainder = dividen;
489						else if (dividen == largest_negative && divisor == -1) remainder = 0;
490						else                                                remainder = dividen % divisor;
491						rd_data[t].i = remainder;
492					}
493				}
494			} break;
495			case MdvType::REMU: {
496				for (uint32_t t = thread_start; t < num_threads; ++t) {
497					if (!tmask.test(t)) continue;
498					if (is_w_enabled && mdvArgs.is_w) {
499						auto dividen = (uint32_t)rs1_data[t].u32;
500						auto divisor = (uint32_t)rs2_data[t].u32;
501						uint32_t remainder;
502						if (divisor != 0) remainder = dividen % divisor;
503						else              remainder = dividen;
504						rd_data[t].i = sext((uint64_t)remainder, 32);
505					} else {
506						auto dividen = rs1_data[t].u;
507						auto divisor = rs2_data[t].u;
508						Word remainder;
509						if (rs2_data[t].i != 0) remainder = dividen % divisor;
510						else                    remainder = dividen;
511						rd_data[t].i = remainder;
512					}
513				}
514			} break;
515			default:
516				std::abort();
517			}
518			DT(3, this->name() << " execute: op=" << mdv_type << ", " << *trace);
519		} else {
520			std::abort();
521		}
522	}
523	
524	void AluUnit::on_tick() {
525	  for (uint32_t b = 0; b < VX_CFG_NUM_ALU_BLOCKS; ++b) {
526			auto& input = Inputs.at(b);
527			if (input.empty())
528				continue;
529			auto& output = Outputs.at(b);
530			if (output.full())
531				continue; // stall
532			auto trace = input.peek();
533	    this->execute(trace);
534			uint32_t delay = this->latency_of(trace);
535			output.send(trace, delay);
536			input.pop();
537		}
538	}
