28	namespace {
29	inline uint64_t nan_box(uint32_t value) {
30	  return value | 0xffffffff00000000;
31	}
32	inline bool is_nan_boxed(uint64_t value) {
33	  return (uint32_t(value >> 32) == 0xffffffff);
34	}
35	inline int64_t check_boxing(int64_t a) {
36	  if (is_nan_boxed(a))
37	    return a;
38	  return nan_box(0x7fc00000); // NaN
39	}
40	}
41	
42	FpuUnit::FpuUnit(const SimContext& ctx, const char* name, Core* core)
43		: FuncUnit<VX_CFG_NUM_FPU_BLOCKS>(ctx, name, core)
44	{}
45	
46	uint32_t FpuUnit::latency_of(const instr_trace_t* trace) const {
47		auto fpu_type = std::get<FpuType>(trace->op_type);
48		const uint32_t delay = 2;
49		switch (fpu_type) {
50		case FpuType::FCMP:
51		case FpuType::FSGNJ:
52		case FpuType::FCLASS:
53		case FpuType::FMVXW:
54		case FpuType::FMVWX:
55		case FpuType::FMINMAX:
56			return 2+delay;
57		case FpuType::FADD:
58		case FpuType::FSUB:
59		case FpuType::FMUL:
60		case FpuType::FMADD:
61		case FpuType::FMSUB:
62		case FpuType::FNMADD:
63		case FpuType::FNMSUB:
64			return VX_CFG_FMA_LATENCY+delay;
65		case FpuType::FDIV:
66			return VX_CFG_FDIV_LATENCY+delay;
67		case FpuType::FSQRT:
68			return VX_CFG_FSQRT_LATENCY+delay;
69		case FpuType::F2I:
70		case FpuType::I2F:
71		case FpuType::F2F:
72			return VX_CFG_FCVT_LATENCY+delay;
73		default:
74			std::abort();
75		}
76	}
77	
78	void FpuUnit::execute(instr_trace_t* trace) {
79		auto& emu = core_->csr_unit();           // CSR/FCSR helpers
80		// Use trace->tmask captured at issue, not the live warp.tmask; divergent
81		// control flow may change the warp's tmask before this trace executes.
82		auto& tmask = trace->tmask;
83		auto& instr = *trace->instr_ptr;
84		auto instrArgs = instr.get_args();
85		auto fpuArgs = std::get<IntrFpuArgs>(instrArgs);
86		auto fpu_type = std::get<FpuType>(trace->op_type);
87		uint32_t wid = trace->wid;
88		uint32_t num_threads = VX_CFG_NUM_THREADS;
89		auto& rs1_data = trace->src_data[0];
90		auto& rs2_data = trace->src_data[1];
91		auto& rs3_data = trace->src_data[2];
92	
93		uint32_t thread_start = 0;
94		for (; thread_start < num_threads; ++thread_start) {
95			if (tmask.test(thread_start)) break;
96		}
97	
98		trace->dst_data.assign(num_threads, reg_data_t{});
99		auto& rd_data = trace->dst_data;
100	
101		switch (fpu_type) {
102		case FpuType::FADD: {
103			for (uint32_t t = thread_start; t < num_threads; ++t) {
104				if (!tmask.test(t)) continue;
105				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
106				uint32_t fflags = 0;
107				if (fpuArgs.is_f64) {
108					rd_data[t].u64 = rv_fadd_d(rs1_data[t].u64, rs2_data[t].u64, frm, &fflags);
109				} else {
110					rd_data[t].u64 = nan_box(rv_fadd_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), frm, &fflags));
111				}
112				emu.update_fcrs(fflags, wid, t);
113			}
114		} break;
115		case FpuType::FSUB: {
116			for (uint32_t t = thread_start; t < num_threads; ++t) {
117				if (!tmask.test(t)) continue;
118				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
119				uint32_t fflags = 0;
120				if (fpuArgs.is_f64) {
121					rd_data[t].u64 = rv_fsub_d(rs1_data[t].u64, rs2_data[t].u64, frm, &fflags);
122				} else {
123					rd_data[t].u64 = nan_box(rv_fsub_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), frm, &fflags));
124				}
125				emu.update_fcrs(fflags, wid, t);
126			}
127		} break;
128		case FpuType::FMUL: {
129			for (uint32_t t = thread_start; t < num_threads; ++t) {
130				if (!tmask.test(t)) continue;
131				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
132				uint32_t fflags = 0;
133				if (fpuArgs.is_f64) {
134					rd_data[t].u64 = rv_fmul_d(rs1_data[t].u64, rs2_data[t].u64, frm, &fflags);
135				} else {
136					rd_data[t].u64 = nan_box(rv_fmul_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), frm, &fflags));
137				}
138				emu.update_fcrs(fflags, wid, t);
139			}
140		} break;
141		case FpuType::FDIV: {
142			for (uint32_t t = thread_start; t < num_threads; ++t) {
143				if (!tmask.test(t)) continue;
144				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
145				uint32_t fflags = 0;
146				if (fpuArgs.is_f64) {
147					rd_data[t].u64 = rv_fdiv_d(rs1_data[t].u64, rs2_data[t].u64, frm, &fflags);
148				} else {
149					rd_data[t].u64 = nan_box(rv_fdiv_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), frm, &fflags));
150				}
151				emu.update_fcrs(fflags, wid, t);
152			}
153		} break;
154		case FpuType::FSQRT: {
155			for (uint32_t t = thread_start; t < num_threads; ++t) {
156				if (!tmask.test(t)) continue;
157				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
158				uint32_t fflags = 0;
159				if (fpuArgs.is_f64) {
160					rd_data[t].u64 = rv_fsqrt_d(rs1_data[t].u64, frm, &fflags);
161				} else {
162					rd_data[t].u64 = nan_box(rv_fsqrt_s(check_boxing(rs1_data[t].u64), frm, &fflags));
163				}
164				emu.update_fcrs(fflags, wid, t);
165			}
166		} break;
167		case FpuType::FSGNJ: {
168			for (uint32_t t = thread_start; t < num_threads; ++t) {
169				if (!tmask.test(t)) continue;
170				uint32_t fflags = 0;
171				if (fpuArgs.is_f64) {
172					switch (fpuArgs.frm) {
173					case 0: rd_data[t].u64 = rv_fsgnj_d(rs1_data[t].u64, rs2_data[t].u64); break;
174					case 1: rd_data[t].u64 = rv_fsgnjn_d(rs1_data[t].u64, rs2_data[t].u64); break;
175					case 2: rd_data[t].u64 = rv_fsgnjx_d(rs1_data[t].u64, rs2_data[t].u64); break;
176					}
177				} else {
178					switch (fpuArgs.frm) {
179					case 0: rd_data[t].u64 = nan_box(rv_fsgnj_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64))); break;
180					case 1: rd_data[t].u64 = nan_box(rv_fsgnjn_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64))); break;
181					case 2: rd_data[t].u64 = nan_box(rv_fsgnjx_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64))); break;
182					}
183				}
184				emu.update_fcrs(fflags, wid, t);
185			}
186		} break;
187		case FpuType::FMINMAX: {
188			for (uint32_t t = thread_start; t < num_threads; ++t) {
189				if (!tmask.test(t)) continue;
190				uint32_t fflags = 0;
191				if (fpuArgs.is_f64) {
192					if (fpuArgs.frm) rd_data[t].u64 = rv_fmax_d(rs1_data[t].u64, rs2_data[t].u64, &fflags);
193					else             rd_data[t].u64 = rv_fmin_d(rs1_data[t].u64, rs2_data[t].u64, &fflags);
194				} else {
195					if (fpuArgs.frm) rd_data[t].u64 = nan_box(rv_fmax_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), &fflags));
196					else             rd_data[t].u64 = nan_box(rv_fmin_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), &fflags));
197				}
198				emu.update_fcrs(fflags, wid, t);
199			}
200		} break;
201		case FpuType::FCMP: {
202			for (uint32_t t = thread_start; t < num_threads; ++t) {
203				if (!tmask.test(t)) continue;
204				uint32_t fflags = 0;
205				if (fpuArgs.is_f64) {
206					switch (fpuArgs.frm) {
207					case 0: rd_data[t].i = rv_fle_d(rs1_data[t].u64, rs2_data[t].u64, &fflags); break;
208					case 1: rd_data[t].i = rv_flt_d(rs1_data[t].u64, rs2_data[t].u64, &fflags); break;
209					case 2: rd_data[t].i = rv_feq_d(rs1_data[t].u64, rs2_data[t].u64, &fflags); break;
210					}
211				} else {
212					switch (fpuArgs.frm) {
213					case 0: rd_data[t].i = rv_fle_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), &fflags); break;
214					case 1: rd_data[t].i = rv_flt_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), &fflags); break;
215					case 2: rd_data[t].i = rv_feq_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), &fflags); break;
216					}
217				}
218				emu.update_fcrs(fflags, wid, t);
219			}
220		} break;
221		case FpuType::F2I: {
222			for (uint32_t t = thread_start; t < num_threads; ++t) {
223				if (!tmask.test(t)) continue;
224				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
225				uint32_t fflags = 0;
226				if (fpuArgs.is_f64) {
227					switch (fpuArgs.cvt) {
228					case 0: rd_data[t].i = sext((uint64_t)rv_ftoi_d(rs1_data[t].u64, frm, &fflags), 32); break;
229					case 1: rd_data[t].i = sext((uint64_t)rv_ftou_d(rs1_data[t].u64, frm, &fflags), 32); break;
230					case 2: rd_data[t].i = rv_ftol_d(rs1_data[t].u64, frm, &fflags); break;
231					case 3: rd_data[t].i = rv_ftolu_d(rs1_data[t].u64, frm, &fflags); break;
232					}
233				} else {
234					switch (fpuArgs.cvt) {
235					case 0: rd_data[t].i = sext((uint64_t)rv_ftoi_s(check_boxing(rs1_data[t].u64), frm, &fflags), 32); break;
236					case 1: rd_data[t].i = sext((uint64_t)rv_ftou_s(check_boxing(rs1_data[t].u64), frm, &fflags), 32); break;
237					case 2: rd_data[t].i = rv_ftol_s(check_boxing(rs1_data[t].u64), frm, &fflags); break;
238					case 3: rd_data[t].i = rv_ftolu_s(check_boxing(rs1_data[t].u64), frm, &fflags); break;
239					}
240				}
241				emu.update_fcrs(fflags, wid, t);
242			}
243		} break;
244		case FpuType::I2F: {
245			for (uint32_t t = thread_start; t < num_threads; ++t) {
246				if (!tmask.test(t)) continue;
247				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
248				uint32_t fflags = 0;
249				if (fpuArgs.is_f64) {
250					switch (fpuArgs.cvt) {
251					case 0: rd_data[t].u64 = rv_itof_d(rs1_data[t].i, frm, &fflags); break;
252					case 1: rd_data[t].u64 = rv_utof_d(rs1_data[t].i, frm, &fflags); break;
253					case 2: rd_data[t].u64 = rv_ltof_d(rs1_data[t].i, frm, &fflags); break;
254					case 3: rd_data[t].u64 = rv_lutof_d(rs1_data[t].i, frm, &fflags); break;
255					}
256				} else {
257					switch (fpuArgs.cvt) {
258					case 0: rd_data[t].u64 = nan_box(rv_itof_s(rs1_data[t].i, frm, &fflags)); break;
259					case 1: rd_data[t].u64 = nan_box(rv_utof_s(rs1_data[t].i, frm, &fflags)); break;
260					case 2: rd_data[t].u64 = nan_box(rv_ltof_s(rs1_data[t].i, frm, &fflags)); break;
261					case 3: rd_data[t].u64 = nan_box(rv_lutof_s(rs1_data[t].i, frm, &fflags)); break;
262					}
263				}
264				emu.update_fcrs(fflags, wid, t);
265			}
266		} break;
267		case FpuType::F2F: {
268			for (uint32_t t = thread_start; t < num_threads; ++t) {
269				if (!tmask.test(t)) continue;
270				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
271				uint32_t fflags = 0;
272				if (fpuArgs.is_f64) {
273					rd_data[t].u64 = rv_ftod(check_boxing(rs1_data[t].u64), frm, &fflags);
274				} else {
275					rd_data[t].u64 = nan_box(rv_dtof(rs1_data[t].u64, frm, &fflags));
276				}
277				emu.update_fcrs(fflags, wid, t);
278			}
279		} break;
280		case FpuType::FCLASS: {
281			for (uint32_t t = thread_start; t < num_threads; ++t) {
282				if (!tmask.test(t)) continue;
283				uint32_t fflags = 0;
284				if (fpuArgs.is_f64) {
285					rd_data[t].i = rv_fclss_d(rs1_data[t].u64);
286				} else {
287					rd_data[t].i = rv_fclss_s(check_boxing(rs1_data[t].u64));
288				}
289				emu.update_fcrs(fflags, wid, t);
290			}
291		} break;
292		case FpuType::FMVXW: {
293			for (uint32_t t = thread_start; t < num_threads; ++t) {
294				if (!tmask.test(t)) continue;
295				uint32_t fflags = 0;
296				if (fpuArgs.is_f64) {
297					rd_data[t].u64 = rs1_data[t].u64;
298				} else {
299					uint32_t result = (uint32_t)rs1_data[t].u64;
300					rd_data[t].i = sext((uint64_t)result, 32);
301				}
302				emu.update_fcrs(fflags, wid, t);
303			}
304		} break;
305		case FpuType::FMVWX: {
306			for (uint32_t t = thread_start; t < num_threads; ++t) {
307				if (!tmask.test(t)) continue;
308				uint32_t fflags = 0;
309				if (fpuArgs.is_f64) {
310					rd_data[t].u64 = rs1_data[t].i;
311				} else {
312					rd_data[t].u64 = nan_box((uint32_t)rs1_data[t].i);
313				}
314				emu.update_fcrs(fflags, wid, t);
315			}
316		} break;
317		case FpuType::FMADD: {
318			for (uint32_t t = thread_start; t < num_threads; ++t) {
319				if (!tmask.test(t)) continue;
320				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
321				uint32_t fflags = 0;
322				if (fpuArgs.is_f64) {
323					rd_data[t].u64 = rv_fmadd_d(rs1_data[t].u64, rs2_data[t].u64, rs3_data[t].u64, frm, &fflags);
324				} else {
325					rd_data[t].u64 = nan_box(rv_fmadd_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), check_boxing(rs3_data[t].u64), frm, &fflags));
326				}
327				emu.update_fcrs(fflags, wid, t);
328			}
329		} break;
330		case FpuType::FMSUB: {
331			for (uint32_t t = thread_start; t < num_threads; ++t) {
332				if (!tmask.test(t)) continue;
333				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
334				uint32_t fflags = 0;
335				if (fpuArgs.is_f64) {
336					rd_data[t].u64 = rv_fmsub_d(rs1_data[t].u64, rs2_data[t].u64, rs3_data[t].u64, frm, &fflags);
337				} else {
338					rd_data[t].u64 = nan_box(rv_fmsub_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), check_boxing(rs3_data[t].u64), frm, &fflags));
339				}
340				emu.update_fcrs(fflags, wid, t);
341			}
342		} break;
343		case FpuType::FNMADD: {
344			for (uint32_t t = thread_start; t < num_threads; ++t) {
345				if (!tmask.test(t)) continue;
346				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
347				uint32_t fflags = 0;
348				if (fpuArgs.is_f64) {
349					rd_data[t].u64 = rv_fnmadd_d(rs1_data[t].u64, rs2_data[t].u64, rs3_data[t].u64, frm, &fflags);
350				} else {
351					rd_data[t].u64 = nan_box(rv_fnmadd_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), check_boxing(rs3_data[t].u64), frm, &fflags));
352				}
353				emu.update_fcrs(fflags, wid, t);
354			}
355		} break;
356		case FpuType::FNMSUB: {
357			for (uint32_t t = thread_start; t < num_threads; ++t) {
358				if (!tmask.test(t)) continue;
359				uint32_t frm = emu.get_fpu_rm(fpuArgs.frm, wid, t);
360				uint32_t fflags = 0;
361				if (fpuArgs.is_f64) {
362					rd_data[t].u64 = rv_fnmsub_d(rs1_data[t].u64, rs2_data[t].u64, rs3_data[t].u64, frm, &fflags);
363				} else {
364					rd_data[t].u64 = nan_box(rv_fnmsub_s(check_boxing(rs1_data[t].u64), check_boxing(rs2_data[t].u64), check_boxing(rs3_data[t].u64), frm, &fflags));
365				}
366				emu.update_fcrs(fflags, wid, t);
367			}
368		} break;
369		default:
370			std::abort();
371		}
372		DT(3, this->name() << " execute: op=" << fpu_type << ", " << *trace);
373	}
374	
375	void FpuUnit::on_tick() {
376		for (uint32_t b = 0; b < VX_CFG_NUM_FPU_BLOCKS; ++b) {
377			auto& input = Inputs.at(b);
378			if (input.empty())
379				continue;
380			auto& output = Outputs.at(b);
381			if (output.full())
382				continue; // stall
383			auto trace = input.peek();
384			this->execute(trace);
385			uint32_t delay = this->latency_of(trace);
386			output.send(trace, delay);
387			input.pop();
388		}
389	}
