29	
30	uint32_t LsuUopGen::uop_count(const Instr& instr) {
31	  // PACKLB.F: width=0 (LB), 4 byte-elements
32	  // PACKLH.F: width=1 (LH), 2 halfword-elements
33	  auto args = std::get<IntrLsuArgs>(instr.get_args());
34	  return (args.width == 0) ? 4 : 2;
35	}
36	
37	Instr::Ptr LsuUopGen::get(const Instr& macro_instr, uint32_t uop_index) {
38	  uint64_t parent_uuid = macro_instr.get_uuid();
39	  uint32_t total = uop_count(macro_instr);
40	
41	  // Embed uop_index in the upper bits of the low half of the UUID so that
42	  // each uop has a distinct UUID for trace logging.
43	  uint32_t uuid_hi = (parent_uuid >> 32) & 0xffffffff;
44	  uint32_t uuid_lo = parent_uuid & 0xffffffff;
45	  uint32_t steps_shift = (total > 1) ? (32 - log2ceil(total)) : 0;
46	  uint64_t uop_uuid = (static_cast<uint64_t>(uuid_hi) << 32) | ((uop_index << steps_shift) | uuid_lo);
47	
48	  auto args = std::get<IntrLsuArgs>(macro_instr.get_args());
49	  // Macro encodes elem-size as width: 0=byte (PACKLB), 1=halfword (PACKLH).
50	  // The uop is a regular unsigned load (LBU/LHU = width + 4) so the LSU
51	  // doesn't sign-extend the loaded byte/halfword before the bytesel write.
52	  uint32_t elem_bytes = 1u << args.width;
53	  uint32_t uop_width  = args.width + 4;          // LBU=4, LHU=5
54	  uint32_t byte_off   = uop_index * elem_bytes;  // byte offset in dst register
55	  // Bytesel: data bytes for this uop's elem + NaN-box bytes (4..7) for Float
56	  // dest. The LSU is generic — it reads bytesel and shifts the loaded data
57	  // into place; OpcUnit::writeback OR-merges by mask.
58	  uint8_t  data_mask  = uint8_t(((1u << elem_bytes) - 1u) << byte_off);
59	  bool     dst_float  = (macro_instr.get_dest_reg().type == RegType::Float);
60	  uint8_t  bytesel    = data_mask | (dst_float ? 0xF0 : 0);
61	
62	  auto uop_instr = std::allocate_shared<Instr>(pool_, uop_uuid, FUType::LSU);
63	  uop_instr->set_parent_uuid(parent_uuid);
64	  uop_instr->set_op_type(LsuType::LOAD);
65	  uop_instr->set_dest_reg(macro_instr.get_dest_reg().idx, macro_instr.get_dest_reg().type);
66	  uop_instr->set_src_reg(0, macro_instr.get_src_reg(0).idx, RegType::Integer);
67	  uop_instr->set_src_reg(1, macro_instr.get_src_reg(1).idx, RegType::Integer);
68	  // Per-uop AGU input: stride = uop_index → addr = rs1 + uop_index*rs2 + 0.
69	  uop_instr->set_args(IntrLsuArgs{uop_width, /*stride*/ uop_index, /*offset*/ 0});
70	  uop_instr->set_dst_bytesel(bytesel);
71	  return uop_instr;
72	}
