74	LsuUnit::LsuUnit(const SimContext& ctx, const char* name, Core* core)
75		: FuncUnit<VX_CFG_NUM_LSU_BLOCKS>(ctx, name, core)
76	#ifdef TCU_META_ENABLE
77		, TcuReqIn(this)
78		, TcuRspOut(this)
79	#endif
80		, pending_loads_(0)
