86	// Returns true when all blocks' input queues are empty and no reads are outstanding.
87	bool LsuUnit::drained() const {
88	#ifdef TCU_META_ENABLE
89		// TcuRspOut forwards to the TCU's endpoint, so query via size() (empty()
90		// asserts on forwarding channels).
91		if (!TcuReqIn.empty() || TcuRspOut.size() != 0) {
92			return false;
93		}
94	#endif
95		for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
96			if (!Inputs.at(b).empty()) return false;
97			if (!states_.at(b).req_queue.empty()) return false;
98			if (!states_.at(b).pending_reqs.empty()) return false;
99		}
100		return true;
101	}
102	
103	void LsuUnit::on_reset() {
104		for (auto& state : states_) {
105			state.reset();
106		}
107		pending_loads_ = 0;
108	}
109	
110	void LsuUnit::compute_addrs(uint32_t b, instr_trace_t* trace) {
111		// AGU formula: addr[t] = rs1[t] + stride * rs2[t] + offset
112		auto& state = states_.at(b);
113		state.addr_list.clear();
114		auto* lsu_tag = std::get_if<LsuType>(&trace->op_type);
115		auto* amo_tag = std::get_if<AmoType>(&trace->op_type);
116		const bool is_amo = (amo_tag != nullptr);
117		auto& tmask = trace->tmask;
118		auto& rs1_data = trace->src_data[0];
119		auto& rs2_data = trace->src_data[1];
120		uint32_t num_threads = VX_CFG_NUM_THREADS;
121		uint32_t data_bytes;
122		bool is_write;
123		int64_t  offset;
124		uint32_t stride;
125		if (is_amo) {
126			auto amo_args = std::get<IntrAmoArgs>(trace->instr_ptr->get_args());
127			data_bytes = 1u << (amo_args.width & 0x3);
128			is_write   = false;        // AMO never writes via the regular store path
129			offset     = 0;            // AMO has no immediate offset
130			stride     = 0;            // single-word access — addr = rs1[t]
131		} else {
132			auto lsu_args = std::get<IntrLsuArgs>(trace->instr_ptr->get_args());
133			data_bytes = 1u << (lsu_args.width & 0x3);
134			is_write   = (lsu_tag && *lsu_tag == LsuType::STORE);
135			offset     = lsu_args.offset;
136			stride     = lsu_args.stride;
137			if (is_write && lsu_args.width > 3)
138				std::abort();
139		}
140		// The per-thread slot is tid-stable: entry index == tid, inactive threads
141		// hold a size-0 hole. Lane position downstream is tid % NUM_LSU_LANES, the
142		// same fixed thread-to-port binding the hardware LSU uses. Compacting
143		// active threads into low lanes would let the same thread's consecutive
144		// accesses ride different per-lane channels when the thread mask changes
145		// between them, and the per-bank arbiter could then reorder same-address
146		// requests.
147		for (uint32_t t = 0; t < num_threads; ++t) {
148			mem_addr_size_t e;
149			e.addr = 0;
150			e.size = 0;
151			e.tid  = t;
152			e.data = 0;
153			if (tmask.test(t)) {
154				// AGU result is VX_CFG_XLEN-bit wide.
155				// Cast through Word so 32-bit VX_CFG_XLEN doesn't carry sign-extended
156				// upper bits into the 64-bit address field.
157				e.addr = Word(rs1_data[t].i + (uint64_t)stride * rs2_data[t].u + offset);
158				e.size = data_bytes;
159				if (is_write || is_amo) {
160					// Stores carry rs2 as data; AMOs carry rs2 as the RMW operand
161					// (LR encodes rs2 = x0, so the captured value is 0).
162					e.data = rs2_data[t].u64;
163				}
164			}
165			state.addr_list.push_back(e);
166		}
167		// Trailing holes never issue anything; trim them so the last beat that
168		// carries a request is also the one that marks end-of-packet.
169		while (!state.addr_list.empty() && state.addr_list.back().size == 0) {
170			state.addr_list.pop_back();
171		}
172		state.remain_addrs = state.addr_list.size();
173	}
174	
175	// Per-cycle response handler. Consumes at most one response packet
176	// from lmem_switch and forwards through to writeback when the
177	// originating request retires. Includes the per-lane response
178	// formatter (sign-extend, NaN-box) and the response demux that
179	// matches each fragment back to its in-flight request entry.
180	void LsuUnit::process_response_step(uint32_t b) {
181		auto& lsu_rsp_in = core_->lmem_switch(b)->RspOut;
182		if (lsu_rsp_in.empty())
183			return;
184		auto& state = states_.at(b);
185		auto& lsu_rsp = lsu_rsp_in.peek();
186		auto& entry = state.pending_reqs.at(lsu_rsp.tag);
187	
188	#ifdef TCU_META_ENABLE
189		// TCU metadata response: forward the fragment with the client's tag
190		// restored; no register writeback, no trace retirement.
191		if (entry.is_tcu) {
192			if (TcuRspOut.full())
193				return; // stall
194			LsuRsp fwd = lsu_rsp;
195			fwd.tag = entry.client_tag;
196			TcuRspOut.send(fwd);
197			DT(3, this->name() << " tcu-meta-rsp: " << fwd);
198			entry.count -= lsu_rsp.mask.count();
199			if (entry.count == 0) {
200				state.pending_reqs.release(lsu_rsp.tag);
201			}
202			lsu_rsp_in.pop();
203			return;
204		}
205	#endif
206	
207		auto trace = entry.trace;
208		auto& output = Outputs.at(b);
209		// Only stall if THIS response would terminate the request and the
210		// output is full (we'd lose the trace forwarding). Non-terminal
211		// responses can still update entry state without touching output.
212		bool is_terminal = (entry.count == lsu_rsp.mask.count()) && entry.eop;
213		if (is_terminal && output.full())
214			return; // stall
215		DT(3, this->name() << " mem-rsp: " << lsu_rsp);
216		assert(entry.count != 0);
217	
218		if (entry.is_load) {
219			bool dst_float = (trace->dst_reg.type == RegType::Float);
220			uint32_t data_bytes = 1u << (entry.lsu_args.width & 0x3);
221			uint32_t data_width = 8 * data_bytes;
222			uint8_t  data_bs    = trace->dst_bytesel & 0x0F;
223			uint32_t byte_off   = (data_bs == 0 || data_bs == 0x0F) ? 0
224			                    : (uint32_t)__builtin_ctz(data_bs);
225			bool nan_box = dst_float && (data_bytes < 8);
226	
227			for (uint32_t lane = 0; lane < lsu_rsp.mask.size(); ++lane) {
228				if (!lsu_rsp.mask.test(lane))
229					continue;
230				const auto& lane_info = entry.lanes.at(lane);
231				assert(lsu_rsp.data.at(lane) && "LOAD response must carry line payload");
232				uint32_t off = lane_info.addr & (VX_CFG_MEM_BLOCK_SIZE - 1);
233				uint64_t read_data = 0;
234				std::memcpy(&read_data, lsu_rsp.data.at(lane)->data() + off, data_bytes);
235				// Format the loaded value at low bits per RISC-V load semantics.
236				uint64_t formatted = 0;
237				switch (entry.lsu_args.width) {
238				case 0: // LB
239				case 1: // LH
240					formatted = (uint64_t)(int64_t)sext((Word)read_data, data_width);
241					break;
242				case 2: // LW (sign-ext for Integer dest; raw bits for Float dest, NaN-boxed below)
243					formatted = dst_float ? read_data
244					                       : (uint64_t)(int64_t)sext((Word)read_data, data_width);
245					break;
246				case 3: // LD
247				case 4: // LBU
248				case 5: // LHU
249				case 6: // LWU
250					formatted = read_data;
251					break;
252				default:
253					std::abort();
254				}
255				// Place at bytesel-specified position; OR-in NaN-box for Float dest.
256				auto& dst = entry.trace->dst_data.at(lane_info.tid);
257				dst.u64 = (formatted << (8 * byte_off))
258				        | (nan_box ? 0xFFFFFFFF00000000ull : 0);
259			}
260		}
261		entry.count -= lsu_rsp.mask.count(); // track remaining
262		if (entry.count == 0) {
263			state.pending_reqs.release(lsu_rsp.tag);
264			if (entry.eop) {
265				output.send(trace, 1);
266			}
267		}
268		pending_loads_ -= lsu_rsp.mask.count();
269		lsu_rsp_in.pop();
270	}
271	
272	// Move ONE trace from Inputs[b] into the dispatch-side req_queue per cycle.
273	// At most one transaction/cycle: the trace is not dispatchable until the next
274	// cycle, so req_queue adds a real cycle of latency. A while-loop here would
275	// fabricate write bandwidth and collapse that latency to zero.
276	void LsuUnit::ingest_inputs(uint32_t b) {
277		auto& state = states_.at(b);
278		auto& input = Inputs.at(b);
279		if (input.empty() || state.req_queue.full())
280			return;
281		auto trace = input.peek();
282		// Hold a fence at the input head until req_queue is empty so the
283		// fence becomes the next dispatched item — preserves total
284		// barrier semantics on a per-block basis.
285		auto lsu_type_tag = std::get_if<LsuType>(&trace->op_type);
286		if (lsu_type_tag && *lsu_type_tag == LsuType::FENCE && !state.req_queue.empty())
287			return;
288		state.req_queue.push(trace);
289		input.pop();
290	}
291	
292	// Per-cycle request handler. Dispatches at most one batch (one
293	// memory-side mem_req) per call. The head trace stays at the queue
294	// front until all its batches are issued (req_sent_all-driven).
295	void LsuUnit::process_request_step(uint32_t b) {
296		auto& state = states_.at(b);
297	
298		// Attempt fence release first so a steady stream of TCU client forwards
299		// (which consume the dispatch slot and return) cannot starve it.
300		const bool fence_locked = state.fence.locked();
301		if (fence_locked) {
302			bool released = state.fence.try_release(Outputs.at(b), state.pending_reqs.empty());
303			if (released) {
304				DT(3, this->name() << " fence-unlock: " << state.fence.trace());
305			}
306		}
307	
308	#ifdef TCU_META_ENABLE
309		// TCU metadata client (block 0 only): forward one pending request per
310		// cycle into lmem_switch, ahead of the block's own dispatch. The wire tag
311		// is re-allocated from pending_reqs so it stays unique on the switch; the
312		// client's own tag is restored on the response. An independent client, so
313		// not gated by the fence lock — its entries still hold fence release via
314		// pending_reqs.empty().
315		if (b == 0 && !TcuReqIn.empty()) {
316			if (!state.pending_reqs.full() && !core_->lmem_switch(0)->ReqIn.full()) {
317				LsuReq lsu_req = TcuReqIn.peek();
318				uint32_t count = lsu_req.mask.count();
319				std::vector<mem_addr_size_t> lane_entries(VX_CFG_NUM_LSU_LANES);
320				for (uint32_t i = 0; i < VX_CFG_NUM_LSU_LANES; ++i) {
321					if (!lsu_req.mask.test(i)) {
322						continue;
323					}
324					lane_entries.at(i) = { lsu_req.addrs.at(i), 4, 0, lsu_req.tids.at(i) };
325				}
326				IntrLsuArgs meta_args{};
327				meta_args.width = 2; // 32-bit metadata words
328				pending_req_t entry{nullptr, count, true, std::move(lane_entries), meta_args, true};
329				entry.is_tcu     = true;
330				entry.client_tag = lsu_req.tag;
331				uint32_t tag = state.pending_reqs.allocate(std::move(entry));
332				lsu_req.tag = tag;
333				core_->lmem_switch(0)->ReqIn.send(lsu_req);
334				DT(3, this->name() << " tcu-meta-req: " << lsu_req);
335				TcuReqIn.pop();
336				return; // one request per cycle into the switch
337			}
338		}
339	#endif
340	
341		// No dispatch while a fence is engaged (per-block total barrier); the
342		// release attempt already ran above.
343		if (fence_locked) {
344			return;
345		}
346	
347		if (state.req_queue.empty())
348			return;
349	
350		auto trace = state.req_queue.front();
351		auto* lsu_tag = std::get_if<LsuType>(&trace->op_type);
352		auto* amo_tag = std::get_if<AmoType>(&trace->op_type);
353		if (!lsu_tag && !amo_tag) {
354			// Trace landed on the LSU with neither LsuType nor AmoType. This
355			// would only happen on a build mismatch (VX_CFG_EXT_A_ENABLE off but
356			// decode emitted AmoType, or unrelated op_type alias).
357			std::abort();
358		}
359	#if !VX_CFG_EXT_A_ENABLED
360		if (amo_tag) {
361			// AMO ops are unsupported in this build.
362			std::abort();
363		}
364	#endif
365		const bool is_amo   = (amo_tag != nullptr);
366		const bool is_fence = (lsu_tag && *lsu_tag == LsuType::FENCE);
367		const bool is_write = (lsu_tag && *lsu_tag == LsuType::STORE);
368	
369		if (is_fence) {
370			// Engage fence lock; the next call will try to release it once
371			// the pending-reqs table drains.
372			state.fence.engage(trace);
373			DT(3, this->name() << " fence-lock: " << *trace);
374			state.req_queue.pop();
375			return;
376		}
377	
378		// check pending queue capacity. AMO always needs a return → reserve
379		// like a load, even though it carries write-bearing semantics.
380		if ((!is_write || is_amo) && state.pending_reqs.full()) {
381			if (!trace->log_once(true)) {
382				DT(4, this->name() << " queue-full: " << *trace);
383			}
384			return;
385		} else {
386			trace->log_once(false);
387		}
388	
389		// First time we see this trace: derive the per-lane addr/size/data
390		// list via compute_addrs(). Persists across multi-batch dispatch via
391		// state.remain_addrs; rebuilt only when the previous trace is fully
392		// drained.
393		if (state.remain_addrs == 0) {
394			this->compute_addrs(b, trace);
395		}
396	
397		// AMO always returns to rd, so it is not direct-commit even though it
398		// carries a side-effect write.
399		bool direct_commit = (is_write || 0 == state.addr_list.size()) && !is_amo;
400	
401		// Skip beats whose tid group is entirely inactive — nothing to issue.
402		while (state.remain_addrs != 0) {
403			uint32_t t0 = state.addr_list.size() - state.remain_addrs;
404			uint32_t n  = std::min<uint32_t>(VX_CFG_NUM_LSU_LANES, state.remain_addrs);
405			bool any = false;
406			for (uint32_t i = 0; i < n; ++i) {
407				if (state.addr_list.at(t0 + i).size != 0) {
408					any = true;
409					break;
410				}
411			}
412			if (any)
413				break;
414			state.remain_addrs -= n;
415		}
416	
417		// Check output backpressure AFTER skipping inactive beats: only the last
418		// active beat commits the trace to Outputs, and leading inactive beats can
419		// make this call that last beat even when the entry remain_addrs exceeded a
420		// single beat. Testing full() against the post-skip remainder ensures the
421		// direct-commit send below never overflows.
422		if (direct_commit && state.remain_addrs <= VX_CFG_NUM_LSU_LANES) {
423			if (Outputs.at(b).full())
424				return; // stall
425		}
426	
427		if (state.remain_addrs != 0) {
428			// check lmem switch backpressure
429			if (core_->lmem_switch(b)->ReqIn.full())
430				return; // stall
431	
432			// setup memory request
433			LsuReq lsu_req(VX_CFG_NUM_LSU_LANES);
434			// LsuReq.write is derived from op via is_write(); no separate field.
435			lsu_req.wid = trace->wid;
436			// Typed op (warp-uniform). For AMO, amo_to_memop() picks the family
437			// member; for plain stores/loads, it's ST/LD. AMO MIN/MAX collapse
438			// signed/unsigned into one op + flag.
439			lsu_req.op = is_amo ? amo_to_memop(*amo_tag)
440			            : (is_write ? MemOp::ST : MemOp::LD);
441			if (is_amo) {
442				lsu_req.flags.amo_unsigned = amo_is_unsigned(*amo_tag);
443			}
444			uint32_t t0 = state.addr_list.size() - state.remain_addrs;
445			uint32_t beat_n = std::min<uint32_t>(VX_CFG_NUM_LSU_LANES, state.remain_addrs);
446			std::vector<mem_addr_size_t> lane_entries(VX_CFG_NUM_LSU_LANES);
447			for (uint32_t i = 0; i < beat_n; ++i) {
448				auto& entry = state.addr_list.at(t0 + i);
449				if (entry.size == 0)
450					continue; // inactive tid: keep the lane hole (tid-stable mapping)
451				// Address goes downstream as VA. The per-core dcache MMU
452				// (under VX_CFG_VM_ENABLE) substitutes PA before the request reaches
453				// the cache; with VM off, the address is already the PA.
454				lsu_req.mask.set(i);
455				lsu_req.addrs.at(i) = entry.addr;
456				lane_entries.at(i) = entry;
457				if (is_write || is_amo) {
458					// Package the lane's value into a per-lane block + byteen.
459					// Stores: store data. AMOs: rhs (rs2). The cache extracts
460					// rhs at byte_off using the same path.
461					auto block = make_mem_block();
462					std::memset(block->data(), 0, block->size());
463					uint32_t off = entry.addr & (VX_CFG_MEM_BLOCK_SIZE - 1);
464					for (uint32_t bo = 0; bo < entry.size; ++bo) {
465						(*block)[off + bo] = uint8_t((entry.data >> (8 * bo)) & 0xff);
466					}
467					lsu_req.data.at(i) = block;
468					lsu_req.byteen.at(i) = ((1ull << entry.size) - 1) << off;
469				}
470				// The lane's original thread index rides along so the adapter can
471				// recover hart_id = make_hart_id(cid, wid, tids[i]).
472				lsu_req.tids.at(i) = entry.tid;
473			}
474			state.remain_addrs -= beat_n;
475	
476			uint32_t count = lsu_req.mask.count();
477			bool is_eop = (state.remain_addrs == 0);
478	
479			uint32_t tag = 0;
480			if (!is_write || is_amo) {
481				// pending_reqs allocation: AMOs need a return, so they're tracked
482				// the same way as loads. Encode AMO width in lsu_args so the
483				// existing response formatter sign-extends correctly.
484				IntrLsuArgs entry_args{};
485				if (is_amo) {
486					auto amoArgs = std::get<IntrAmoArgs>(trace->instr_ptr->get_args());
487					entry_args.width  = amoArgs.width & 0x3;
488					entry_args.stride = 0;
489					entry_args.offset = 0;
490				} else {
491					entry_args = std::get<IntrLsuArgs>(trace->instr_ptr->get_args());
492				}
493				tag = state.pending_reqs.allocate({trace, count, is_eop, std::move(lane_entries), entry_args, true});
494			}
495			lsu_req.tag  = tag;
496			lsu_req.cid  = trace->cid;
497			lsu_req.uuid = trace->uuid;
498	
499			// send memory request
500			core_->lmem_switch(b)->ReqIn.send(lsu_req);
501			DT(3, this->name() << " mem-req: " << lsu_req);
502	
503			// update stats
504			if (is_write) {
505				core_->perf_stats().stores += count;
506			} else {
507				core_->perf_stats().loads += count;
508				pending_loads_ += count;
509			}
510		}
511	
512		if (state.remain_addrs == 0) {
513			if (direct_commit) {
514				Outputs.at(b).send(trace);
515			}
516			state.req_queue.pop();
517		}
518	}
519	
520	void LsuUnit::on_tick() {
521		core_->perf_stats().load_latency += pending_loads_;
522	
523		for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
524			// Drain-before-fill ordering: consume responses, dispatch from req_queue
525			// as it stood at the start of this cycle, THEN ingest one new trace for
526			// next cycle. Dispatching before ingest makes req_queue a 1-cycle stage
527			// rather than a same-tick passthrough.
528			this->process_response_step(b);
529			this->process_request_step(b);
530			this->ingest_inputs(b);
531		}
532	}
