103	
104	void SfuUnit::on_tick() {
105	#ifdef VX_CFG_EXT_RTU_ENABLE
106		// Drain RTU rsps. Two flavors:
107		//   TERMINAL — the ray finished; apply hit attrs into the RTU regfile,
108		//              write per-lane status into trace->dst_data, forward the
109		//              parked trace (the TRACE instr) to writeback.
110		//   CB_YIELD — the ray yielded to AHS/IS. Stage candidate-hit attrs +
111		//              cb_type into the yielded lanes' RTU regs and raise an
112		//              async trap on the warp. The trace stays parked in
113		//              RtuCore; a later TERMINAL drains it via the path above.
114		//              See proposal §4.6 (option-c: reuse existing mtvec/MRET).
115		while (!rtu_rsp_in.empty()) {
116			auto& rsp = rtu_rsp_in.peek();
117			if (rsp.kind == RtuRspKind::CB_YIELD) {
118				auto& sched = core_->scheduler();
119				// Phase 3-A2 divergent-SBT: this warp may be running a
120				// previous dispatcher and not yet have executed `mret`.
121				// raising another async-trap on the warp now would
122				// clobber mepc/mtvec, losing the resume PC. Defer until
123				// the in-flight trap is retired.
124				if (sched.in_async_trap(rsp.warp_id)) break;
125				// Also defer if the warp just mret'd this cycle: a back-to-back
126				// mret + async-trap collides on the warp's tmask/PC (restored vs
127				// newly-trapped contexts race), skipping the next dispatcher's
128				// cb_ret. Let the mret settle one cycle (reformation multi-group).
129				if (SimPlatform::instance().cycles() <= sched.last_mret_cycle(rsp.warp_id)) break;
130				rtu_unit_->apply_callback_payload(rsp);
131				auto& warp  = sched.warp(rsp.warp_id);
132				ThreadMask yielded(VX_CFG_NUM_THREADS);
133				for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
134					if ((rsp.cb_active_mask >> t) & 1u) yielded.set(t);
135				}
136				// mepc = current fetch PC. The warp's pipeline still has the
137				// pre-trap instructions (incl. the parked TRACE's scoreboard
138				// dependency on rd) in-flight; the dispatcher's instructions
139				// fire alongside but don't touch TRACE's rd, so they make
140				// progress while the post-WAIT kernel ops stay stalled on
141				// TRACE until the final TERMINAL rsp.
142				constexpr Word TRAP_CAUSE_RTU_CALLBACK = VX_TRAP_CAUSE_RTU_CALLBACK;
143				sched.raise_async_trap(rsp.warp_id, TRAP_CAUSE_RTU_CALLBACK,
144				                       warp.PC, yielded);
145				// Remember which ray's dispatcher is now running (cb_handle =
146				// slot, uniform across yielded lanes) so only THIS ray's TERMINAL
147				// is held off until mret — a recursive traceRay the dispatcher
148				// itself fires must complete normally.
149				for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
150					if ((rsp.cb_active_mask >> t) & 1u) {
151						rtu_trap_slot_.at(rsp.warp_id) = rsp.cb_handle[t];
152						break;
153					}
154				}
155				DT(3, "rtu-cb_yield: core=" << core_->id() << ", wid=" << rsp.warp_id
156				      << ", mask=0x" << std::hex << rsp.cb_active_mask << std::dec);
157				rtu_rsp_in.pop();
158				continue;
159			}
160			// Defer THIS ray's TERMINAL writeback while its callback dispatcher
161			// is still running. A high-pressure dispatcher (e.g. an FP
162			// intersection shader) saves/restores the WAIT's rd register; its
163			// scoreboard reservation was lifted at trap entry and re-installed
164			// at mret, so the status word must not land until after mret —
165			// otherwise the epilogue restore would clobber it. Only the
166			// trap-triggering ray (rtu_trap_slot_) is held off; a nested
167			// recursive traceRay must drain normally or the dispatcher (blocked
168			// on the nested wait) would deadlock.
169			if (core_->scheduler().in_async_trap(rsp.warp_id)
170			    && rsp.slot_idx == rtu_trap_slot_.at(rsp.warp_id)) break;
171			// §8.6 TERMINAL: route to the parked WAIT trace (if WAIT
172			// already issued) or latch into pending_terminals_ (if
173			// WAIT hasn't issued yet — slot is short-lived enough
174			// that TERMINAL beat WAIT to the SFU). The TRACE trace
175			// is NOT used here — TRACE's writeback already happened
176			// synchronously at vx_rt_trace dispatch (its dst_data
177			// carries the slot handle). Pre-check output.full() before
178			// calling on_terminal_rsp because the latter is destructive
179			// (frees the slot and erases the parked entry).
180			uint32_t bid = 0;
181			if (rtu_unit_->terminal_would_writeback(rsp, &bid)
182			    && Outputs.at(bid).full()) {
183				break;  // backpressure: retry next tick
184			}
185			auto wb = rtu_unit_->on_terminal_rsp(rsp);
186			if (wb.trace) {
187				Outputs.at(wb.block_id).send(wb.trace, this->latency_of(wb.trace));
188				DT(3, "rtu-rsp deliver: core=" << core_->id()
189					 << ", wid=" << wb.trace->wid << ", slot=" << rsp.slot_idx);
190			} else {
191				DT(3, "rtu-rsp latch: core=" << core_->id()
192					 << ", wid=" << rsp.warp_id << ", slot=" << rsp.slot_idx);
193			}
194			rtu_rsp_in.pop();
195		}
196	#endif
197	
198	#ifdef VX_CFG_EXT_TEX_ENABLE
199		// Drain TEX completions FIRST. TexCore returns each finished trace via
200		// tex_rsp_in; copy filtered texels into dst_data and forward the trace
201		// onto the originally-recorded writeback output lane.
202		while (!tex_rsp_in.empty()) {
203			auto& rsp = tex_rsp_in.peek();
204			// Single (and legacy vx_tex) retire on their one response; a quad retires
205			// only on its 4th fragment — frags 0..2 just land their texel in the window.
206			bool retire = !rsp.is_quad || (rsp.frag == 3);
207			auto& output = Outputs.at(rsp.block_id);
208			if (retire && output.full())
209				break;
210			instr_trace_t* trace = rsp.trace;
211			for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
212				if (!trace->tmask.test(t)) continue;
213	#ifdef VX_GFX_WINDOW_ENABLE
214				// vx_tex4: land this fragment's texel in the window at out_slot+frag.
215				if (rsp.is_tex4)
216					gfx_window_.set(trace->wid, t, (rsp.out_slot + rsp.frag) & 0x1f, rsp.texels[t]);
217	#endif
218				if (retire)
219					trace->dst_data[t].i = rsp.texels[t];   // rd = scoreboard sync handle
220			}
221			if (rsp.is_quad) {
222				// advance the per-block fragment sequencer; the input was held across
223				// the four issues and is released here on the last response.
224				q_issued_[rsp.block_id] = 0;
225				if (rsp.frag == 3) { q_frag_[rsp.block_id] = 0; Inputs.at(rsp.block_id).pop(); }
226				else ++q_frag_[rsp.block_id];
227			}
228			if (retire) {
229				// Unit latency is already modeled by the TEX pipeline; charge only
230				// the gather/writeback hop.
231				output.send(trace, 2);
232				DT(3, "tex-rsp deliver: core=" << core_->id() << ", wid=" << trace->wid);
233			}
234			tex_rsp_in.pop();
235		}
236	#endif
237	
238	#ifdef VX_CFG_EXT_RASTER_ENABLE
239		{
240			// RASTER dispatch v2 (push). The per-core fragment work distributor pulls
241			// covered-quad waves from the cluster RasterCore autonomously (no kernel
242			// op): each tick post RasterReqs while the producer is armed and has
243			// request budget, then convert each RasterRsp into a FwdWave the scheduler
244			// launches as a fragment warp (payload seeded into the warp's register
245			// window at launch). An all-zero (pos_mask==0) rsp is the drained sentinel.
246			auto& sched = core_->scheduler();
247	
248			// 1) Autonomous wave-pull: keep the producer fed while armed.
249			while (sched.fwd_armed() && sched.fwd_can_request()
250			    && !sched.fwd_wave_queue_full() && !raster_req_out.full()) {
251				RasterReq req;
252				req.uuid       = 0;
253				req.tag        = 0;
254				req.core_id    = core_->id();
255				req.trace      = nullptr;   // autonomous pull — no kernel trace
256				req.block_id   = 0;
257				req.tmask_bits = (VX_CFG_NUM_THREADS >= 32)
258				               ? 0xffffffffu : ((1u << VX_CFG_NUM_THREADS) - 1u);
259				raster_req_out.send(req);
260				sched.fwd_on_request();
261			}
262	
263			// 2) Drain responses, compacting covered quads across responses into full
264			//    NUM_THREADS warps (mirror of VX_raster_packer): launch one warp per
265			//    full/flushed pack, not one per sparse response. Image-neutral.
266			auto fwd_flush_pack = [&]() {
267				if (fwd_pack_count_ == 0) return;
268				Scheduler::FwdWave wave;
269				for (uint32_t j = 0; j < fwd_pack_count_; ++j) {
270					wave.tmask.set(j);
271					wave.payload[j] = fwd_pack_buf_[j];
272				}
273				sched.fwd_push_wave(wave);
274				fwd_pack_count_ = 0;
275			};
276			while (!raster_rsp_in.empty()) {
277				auto& rsp = raster_rsp_in.peek();
278				bool drained = true;
279				for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t)
280					if (rsp.stamps[t].pos_mask != 0) drained = false;
281				if (drained) {
282					fwd_flush_pack();               // flush the tail partial warp
283					sched.fwd_mark_drained();
284				} else {
285					for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
286						const auto& s = rsp.stamps[t];
287						// Skip uncovered quads (coverage nibble empty): block batches
288						// carry mask=0 fillers with valid positions that must not
289						// occupy a wave lane.
290						if ((s.pos_mask & 0xf) == 0) continue;
291						// Never co-pack two quads at the same (pos_x,pos_y): flush first
292						// so same-pixel fragments land in distinct, ordered warps.
293						bool collide = false;
294						for (uint32_t j = 0; j < fwd_pack_count_; ++j)
295							if ((fwd_pack_buf_[j].pos_mask >> 4) == (s.pos_mask >> 4)) collide = true;
296						if (collide || fwd_pack_count_ == VX_CFG_NUM_THREADS)
297							fwd_flush_pack();
298						fwd_pack_buf_[fwd_pack_count_].pos_mask = s.pos_mask;
299						fwd_pack_buf_[fwd_pack_count_].pid      = s.pid;
300						if (++fwd_pack_count_ == VX_CFG_NUM_THREADS)
301							fwd_flush_pack();
302					}
303				}
304				sched.fwd_on_response();
305				raster_rsp_in.pop();
306			}
307	
308			// 3) Epoch complete (producer drained AND every launched wave retired):
309			//    return the core to idle so run()/busy can settle.
310			if (sched.fwd_done())
311				sched.fwd_disarm();
312		}
313	#endif
314	
315		// PE switch: peek input, route to the matching sub-unit (WCTL / CSR /
316		// DXA / TEX / OM / RASTER) by op_type, gather to the single result port.
317		for (uint32_t b = 0; b < VX_CFG_NUM_SFU_BLOCKS; ++b) {
318			auto& input = Inputs.at(b);
319			if (input.empty())
320				continue;
321			auto& output = Outputs.at(b);
322			auto trace = input.peek();
323	
324	#ifdef VX_CFG_EXT_TEX_ENABLE
325			// TEX path is async: don't gate on output.full() yet — that check
326			// happens on completion. Submit only.
327			if (std::get_if<TexType>(&trace->op_type)) {
328	#ifdef VX_GFX_WINDOW_ENABLE
329				// vx_tex4: source the payload from the shared graphics window (staged by
330				// SETW) so TexUnit::process sees the legacy operand layout (u=src0,
331				// v=src1, lod=src2). src_data is always NUM_SRC_REGS-wide.
332				auto targs = std::get<IntrTexArgs>(trace->instr_ptr->get_args());
333				if (targs.is_tex4 && targs.mode) {
334					// quad mode: one fragment in flight. Cache rs1(dims)/rs2(in_slot) at
335					// fragment 0 (src_data is overwritten per fragment below), compute the
336					// integer LOD from the quad derivatives, and issue fragment F. The
337					// frag-3 response retires the op and pops the input.
338					if (q_issued_[b]) continue;
339					uint32_t F = q_frag_[b];
340					if (F == 0) {
341						for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
342							if (!trace->tmask.test(t)) continue;
343							q_in_slot_[b] = trace->src_data[1].at(t).u & 0x1f;
344							q_dims_[b]    = trace->src_data[0].at(t).u;
345							break;
346						}
347					}
348					uint32_t logw = q_dims_[b] & 0xffff, logh = q_dims_[b] >> 16;
349					for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
350						if (!trace->tmask.test(t)) continue;
351						int32_t u[4], v[4];
352						for (int k = 0; k < 4; ++k) {
353							u[k] = (int32_t)gfx_window_.get(trace->wid, t, (q_in_slot_[b] + k) & 0x1f);
354							v[k] = (int32_t)gfx_window_.get(trace->wid, t, (q_in_slot_[b] + 4 + k) & 0x1f);
355						}
356						uint32_t lod = vx_tex_quad_lod(u, v, logw, logh);
357						trace->src_data[0].at(t).u = (uint32_t)u[F];
358						trace->src_data[1].at(t).u = (uint32_t)v[F];
359						trace->src_data[2].at(t).u = lod;
360					}
361					if (!tex_unit_->process(trace, b, F))
362						continue; // backpressure
363					q_issued_[b] = 1;
364					continue;     // do NOT pop — the frag-3 response pops the input
365				}
366				if (targs.is_tex4) {
367					// single mode: u at in_slot, v at in_slot+1, lod from rs1.
368					for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
369						if (!trace->tmask.test(t)) continue;
370						uint32_t in_slot = trace->src_data[1].at(t).u & 0x1f;
371						uint32_t lod     = trace->src_data[0].at(t).u;
372						trace->src_data[0].at(t).u = gfx_window_.get(trace->wid, t, in_slot);
373						trace->src_data[1].at(t).u = gfx_window_.get(trace->wid, t, (in_slot + 1) & 0x1f);
374						trace->src_data[2].at(t).u = lod;
375					}
376				}
377	#endif
378				if (!tex_unit_->process(trace, b))
379					continue; // backpressure — leave trace in input, retry next cycle
380				input.pop();
381				continue;
382			}
383	#endif
384	
385	#ifdef VX_CFG_EXT_OM_ENABLE
386			// vx_om4: one thread owns a 2x2 quad. Emit one OmReq per covered
387			// sub-pixel F (0..3), skipping sub-pixels no lane covers, reading
388			// colour[F]/depth[F] from the shared window; retire (send+pop, no rd)
389			// after the last sub-pixel.
390			if (std::get_if<OmType>(&trace->op_type)) {
391	#ifdef VX_GFX_WINDOW_ENABLE
392				if (!om_last_sent_[b]) {
393					uint32_t F = om_q_frag_[b];
394					// Capture desc/base ONCE per op (see om_captured_): the loop below
395					// overwrites src_data in place, so a re-entry must not re-read it.
396					if (!om_captured_[b]) {
397						om_captured_[b] = 1;
398						for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t)
399							om_desc_[b][t] = trace->src_data[0].at(t).u;
400						for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
401							if (!trace->tmask.test(t)) continue;
402							om_base_[b] = trace->src_data[1].at(t).u & 0x1f;
403							break;
404						}
405						// Latch the full colour/depth payload now: the op has no
406						// completion handle, so the window can be re-seeded for the
407						// next fragment CTA before later sub-pixels are emitted.
408						for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
409							if (!trace->tmask.test(t)) continue;
410							for (uint32_t k = 0; k < 4; ++k) {
411								om_color_[b][t][k] = (uint32_t)gfx_window_.get(trace->wid, t, (om_base_[b] + k) & 0x1f);
412								om_depth_[b][t][k] = (uint32_t)gfx_window_.get(trace->wid, t, (om_base_[b] + 4 + k) & 0x1f);
413							}
414						}
415					}
416					uint32_t fmask = 0;
417					for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
418						if (!trace->tmask.test(t)) continue;
419						uint32_t desc = om_desc_[b][t];
420						if (!((desc >> F) & 0x1)) continue;   // lane not covered for F
421						uint32_t qx   = (desc >> 4) & ((1u << (VX_RASTER_DIM_BITS - 1)) - 1);
422						uint32_t qy   = (desc >> (4 + (VX_RASTER_DIM_BITS - 1))) & ((1u << (VX_RASTER_DIM_BITS - 2)) - 1);
423						uint32_t face = (desc >> 31) & 0x1;
424						uint32_t pos_x = (qx << 1) | (F & 1);
425						uint32_t pos_y = (qy << 1) | ((F >> 1) & 1);
426						trace->src_data[0].at(t).u = (pos_y << 16) | (pos_x << 1) | face;
427						trace->src_data[1].at(t).u = om_color_[b][t][F];
428						trace->src_data[2].at(t).u = om_depth_[b][t][F];
429						fmask |= (1u << t);
430					}
431					if (fmask != 0 && !om_unit_->process(trace, fmask))
432						continue; // OM bus backpressure — retry this sub-pixel
433					if (F < 3) { om_q_frag_[b] = F + 1; continue; }
434					om_last_sent_[b] = 1;
435				}
436				if (output.full())
437					continue; // last sub-pixel submitted; retire when output frees
438				om_q_frag_[b]    = 0;
439				om_last_sent_[b] = 0;
440				om_captured_[b]  = 0;
441				output.send(trace, this->latency_of(trace));
442				input.pop();
443				continue;
444	#endif
445			}
446	#endif
447	
448	#ifdef VX_GFX_WINDOW_ENABLE
449			// Graphics-window / RTU dispatch. SETW (write) and GETW/GETWF (windowed
450			// read) are pure register-window ops, available whenever any FF consumer
451			// is built. The RTU-specific ops (CB_RET / TRACE2 / WAIT2) are gated on
452			// VX_CFG_EXT_RTU_ENABLE — they are only ever decoded with the RTU built,
453			// and they touch rtu_unit_ which does not exist otherwise.
454			//   SETW / GETW[F]      — synchronous graphics-window updates / reads.
455			//   TRACE2              — synchronous writeback of the slot handle; the
456			//                          ray walks async in RtuCore.
457			//   WAIT2               — fast path (short-circuit) when the TERMINAL
458			//                          already landed; otherwise parked in RtuUnit.
459			//   CB_RET              — async (TEX-shape): submit, drop input.
460			if (auto rtu_p = std::get_if<RtuType>(&trace->op_type)) {
461	#ifdef VX_CFG_EXT_RTU_ENABLE
462				if (*rtu_p == RtuType::CB_RET) {
463					// Phase 2: send the per-lane action to RtuCore via the bus
464					// and retire the CB_RET op synchronously (no rd). The
465					// dispatcher follows up with `mret` to resume the kernel
466					// at the post-WAIT PC.
467					if (!rtu_unit_->process_cb_ret(trace, b))
468						continue; // backpressure
469					if (output.full()) continue;
470					output.send(trace, this->latency_of(trace));
471					input.pop();
472					continue;
473				}
474				// ISA v2 (rtu_isa_v2_proposal.md §5.6): each TRACE2/WAIT2 macro-op
475				// arrives here already expanded by the per-warp sequencer into
476				// micro-ops; args.uop is the micro-op index.
477				if (*rtu_p == RtuType::TRACE2) {
478					// All 4 uops complete synchronously (the async traversal kicks
479					// off when uop 3 arms the slot). Backpressure: pool full at
480					// uop 0, bus full at uop 3 — retry the same uop next cycle.
481					auto args = std::get<IntrRtuArgs>(trace->instr_ptr->get_args());
482					if (output.full()) continue;
483					if (!rtu_unit_->process_trace2_uop(trace, b, args.uop))
484						continue;
485					output.send(trace, this->latency_of(trace));
486					input.pop();
487					continue;
488				}
489				if (*rtu_p == RtuType::WAIT2) {
490					// single-op block. Identical park / short-circuit to v1
491					// WAIT, so it survives an async callback trap (parked traces are
492					// revived by on_terminal_rsp; a macro-op could not be). The hit
493					// window is delivered by the separate WAIT_WB that follows.
494					uint32_t slot = rtu_unit_->wait_handle(trace);
495					if (rtu_unit_->wait_would_short_circuit(trace->wid, slot)
496					    && output.full()) {
497						continue;
498					}
499					instr_trace_t* wb = rtu_unit_->process_wait(trace, b);
500					if (wb) {
501						output.send(wb, this->latency_of(wb));
502					}
503					input.pop();
504					continue;
505				}
506	#endif // VX_CFG_EXT_RTU_ENABLE
507				// GETWF / GETW: FP / GP windowed read, expanded by the
508				// sequencer into one synchronous uop per window slot (args.uop = slot
509				// offset). Reads are synchronous; any ordering vs terminal is enforced
510				// by the optional rs1 scoreboard chain (vx_rt_wait2 sets it to status).
511				if (*rtu_p == RtuType::GETWF || *rtu_p == RtuType::GETW) {
512					auto args = std::get<IntrRtuArgs>(trace->instr_ptr->get_args());
513					if (output.full()) continue;
514					gfx_window_.process_getw_uop(trace, args.uop, *rtu_p == RtuType::GETWF);
515					output.send(trace, this->latency_of(trace));
516					input.pop();
517					continue;
518				}
519				// GETWS: GP windowed read indexed by rs1 (block_idx) — the FWD-v2
520				// fragment-record read (single-slot; block_idx recovered from CTA_BLOCK_ID).
521				if (*rtu_p == RtuType::GETWS) {
522					auto args = std::get<IntrRtuArgs>(trace->instr_ptr->get_args());
523					if (output.full()) continue;
524					gfx_window_.process_getws_uop(trace, args.uop);
525					output.send(trace, this->latency_of(trace));
526					input.pop();
527					continue;
528				}
529				// SETW: synchronous regfile write (callback writeback).
530				if (output.full()) continue;
531				gfx_window_.process_set(trace);
532				output.send(trace, this->latency_of(trace));
533				input.pop();
534				continue;
535			}
536	#endif // VX_GFX_WINDOW_ENABLE
537	
538			// RASTER dispatch v2 is push, not pull: there is no kernel-side raster op.
539			// The fragment work distributor (above + scheduler) launches fragment
540			// warps directly from the autonomously-pulled covered-quad waves.
541	
542			if (output.full())
543				continue; // stall — no side effects this tick
544	
545			// WSYNC has a structural gate: cannot complete until prior insts retire.
546			// BAR (vx_barrier and vx_barrier_arrive) drains LSU before continuing —
547			// implements CUDA __syncthreads / OpenCL barrier(CLK_LOCAL_MEM_FENCE) semantic.
548			if (auto wctl_p = std::get_if<WctlType>(&trace->op_type)) {
549				if (trace->eop) {
550					if (*wctl_p == WctlType::WSYNC) {
551						if (core_->has_pending_instrs(trace->wid))
552							continue; // wait for the warp's prior instrs to retire
553					} else if (*wctl_p == WctlType::BAR) {
554						if (!core_->lsu_drained())
555							continue; // drain LSU before the barrier
556					}
557				}
558			}
559	
560			bool release_warp = trace->fetch_stall;
561			if (std::get_if<WctlType>(&trace->op_type)) {
562				release_warp = wctl_unit_->process(trace);
563			} else if (std::get_if<CsrType>(&trace->op_type)) {
564				csr_unit_->process(trace);
565	#ifdef VX_CFG_EXT_DXA_ENABLE
566			} else if (std::get_if<DxaType>(&trace->op_type)) {
567				// process() returns nullptr on backpressure (idempotent retry next
568				// cycle) or the trace on success → fall through to send/pop.
569				if (!dxa_unit_->process(trace)) {
570					continue;
571				}
572	#endif
573			}
574	
575			uint32_t delay = this->latency_of(trace);
576			output.send(trace, delay);
577			// Warp-control refines the default (fetch_stall) release decision: a
578			// sync-barrier, a not-yet-last barrier arrival, a deferred wspawn, or a
579			// warp that disabled itself (tmask=0) keeps the warp parked — it is
580			// released by the barrier/spawn machinery rather than at this commit.
581			trace->resume_warp = release_warp;
582	
583			input.pop();
584		}
585	}
