18	
19	Dispatcher::Dispatcher(const SimContext& ctx, const char* name, Core* core, uint32_t buf_size, uint32_t block_size, uint32_t num_lanes)
20	  : SimObject<Dispatcher>(ctx, name)
21	  , Inputs(VX_CFG_ISSUE_WIDTH, this)
22	  // physical block count, matches downstream FU; each output is the per-FU
23	  // dispatch queue, depth = VX_CFG_DISPATCH_QUEUE_SIZE.
24	  , Outputs(block_size, SimChannel<instr_trace_t*>(this, buf_size))
25	  , core_(core)
26	  , block_size_(block_size)
27	  , num_lanes_(num_lanes)
28	  , num_blocks_(VX_CFG_ISSUE_WIDTH / block_size)
29	  , num_packets_(VX_CFG_NUM_THREADS / num_lanes)
30	  , batch_idx_(0)
31	  , block_pids_(block_size, 0)
32	{}
33	
34	Dispatcher::~Dispatcher() {}
35	
36	void Dispatcher::on_reset() {
37	  batch_idx_ = 0;
38	  for (auto& bp : block_pids_) {
39	    bp = 0;
40	  }
41	}
42	
43	void Dispatcher::on_tick() {
44	  // process inputs
45	  uint32_t block_sent = 0;
46	  for (uint32_t b = 0; b < block_size_; ++b) {
47	    uint32_t i = batch_idx_ * block_size_ + b;
48	    auto& input = Inputs.at(i);
49	    if (input.empty()) {
50	      ++block_sent;
51	      continue;
52	    }
53	
54	    // check output buffer capacity — outputs are sized NUM_BLOCKS;
55	    // input[batch_idx*block_size + b] aggregates onto output[b].
56	    auto& output = Outputs.at(b);
57	    if (output.full())
58	      continue;
59	
60	    auto trace = input.peek();
61	
62	    // check if trace should be split
63	    auto new_trace = trace;
64	    if (num_packets_ != 1) {
65	      auto block_pid = block_pids_.at(b);
66	      // check if current block has already been processed
67	      if (block_pid == -1) {
68	        ++block_sent;
69	        continue;
70	      }
71	      // Compute the total number of packets we'll emit on the first call
72	      // for this trace (block_pid==0). Each SIMD group with any active
73	      // lane gets one packet; sparse divergent tmasks emit fewer than
74	      // num_packets_. Commit uses num_pkts to defer the scoreboard
75	      // release until every packet's writeback has applied — without it,
76	      // an eop packet that completes ahead of its peers (cache responses
77	      // arrive out of order) would release the destination while some
78	      // lanes are still stale.
79	      if (block_pid == 0) {
80	        uint32_t n_pkts = 0;
81	        for (uint32_t j = 0; j < VX_CFG_NUM_THREADS; j += num_lanes_) {
82	          for (uint32_t k = 0; k < num_lanes_; ++k) {
83	            if (trace->tmask.test(j + k)) { ++n_pkts; break; }
84	          }
85	        }
86	        trace->num_pkts = n_pkts == 0 ? 1 : n_pkts;
87	      }
88	      // calculate current packet start and end
89	      int start(-1), end(-1);
90	      for (uint32_t j = block_pid * num_lanes_, n = VX_CFG_NUM_THREADS; j < n; ++j) {
91	        if (!trace->tmask.test(j))
92	          continue;
93	        if (start == -1)
94	          start = j;
95	        end = j;
96	      }
97	      start /= num_lanes_;
98	      end /= num_lanes_;
99	
100	      // issue partial trace
101	      if (start != end) {
102	        auto trace_alloc = core_->trace_pool().allocate(1);
103	        new_trace = new (trace_alloc) instr_trace_t(*trace);
104	        block_pids_.at(b) = start + 1;
105	      } else {
106	        block_pids_.at(b) = -1; // mark block as processed
107	        input.pop();
108	        ++block_sent;
109	      }
110	      ThreadMask tmask(VX_CFG_NUM_THREADS);
111	      for (int j = start * num_lanes_, n = j + num_lanes_; j < n; ++j) {
112	        tmask[j] = trace->tmask[j];
113	      }
114	      new_trace->tmask = tmask;
115	      new_trace->pid = start;
116	      new_trace->sop = trace->sop && (0 == block_pid);
117	      new_trace->eop = trace->eop && (start == end);
118	    } else {
119	      // issue the trace
120	      input.pop();
121	      ++block_sent;
122	    }
123	    DT(3, this->name() << "-pipeline dispatch: " << *new_trace);
124	    output.send(new_trace, 1);
125	  }
126	
127	  // advance to next batch once all blocks in the current batch have been processed
128	  if (block_sent == block_size_) {
129	    // round-robin batch selection
130	    batch_idx_ = (batch_idx_ + 1) % num_blocks_;
131	    for (auto& bp : block_pids_) {
132	      bp = 0;
133	    }
134	  }
135	};
